import { describe, expect, it } from "vitest";
import { existsSync } from "node:fs";
import {
  apiFetchAsRunner,
  authedRequest,
  createRealApiApp,
  loginAsAdmin,
} from "./acceptance-test-support";
import {
  runBoardPollCycle,
  type TrelloIngestionBoardConfig,
  type TrelloIngestionPollerDependencies,
} from "./trello-ingestion-poller";
import { createHttpGovernanceRepository } from "./http-governance-repository";
import type { TrelloIngestionPort } from "./trello-ingestion-port";
import type { TrelloCardSnapshot } from "./types";

// US-11: Ticket Ingested From an External Board (Trello) Triggers the Same Flow as a Native
// Ticket. Traceability: docs/feature/multi-source-ingestion-governance/discuss/user-stories.md
// US-11.
//
// Walking-Skeleton Strategy B (see distill/wave-decisions.md DWD-01): real SQLite + real Hono
// API app for all local I/O (@real-io); the Trello CLI integration itself is faked via an
// in-memory TrelloIngestionPort test double (@in-memory) since it is a costly, rate-limited
// external dependency. agent-runner's own calls to the API (via GovernanceRepositoryPort)
// authenticate server-to-server with the runner token, never a human browser session — human
// actions (registering a board) authenticate with a logged-in session, per
// acceptance-test-support.ts.

function createFakeTrelloIngestionPort(
  cardsByBoard: Record<string, TrelloCardSnapshot[] | (() => Promise<TrelloCardSnapshot[]>)>,
): TrelloIngestionPort {
  return {
    async listCards({ boardId }) {
      const entry = cardsByBoard[boardId];
      if (!entry) {
        throw new Error(`fake Trello board unreachable: no double configured for "${boardId}"`);
      }
      return typeof entry === "function" ? entry() : entry;
    },
  };
}

function makeCard(overrides: Partial<TrelloCardSnapshot> = {}): TrelloCardSnapshot {
  return {
    id: "card-1043",
    name: "Add filter by region to Reports dashboard",
    description: "Maria wants a region filter on the Reports dashboard.",
    listId: "list-backlog",
    listName: "Backlog",
    url: "https://trello.com/c/card-1043",
    ...overrides,
  };
}

describe("US-11: Trello board ingestion behaves like the native ticket form", () => {
  // DEFERRED: needs a real `tickets` row (ticket-classification's POST /api/tickets insert
  // logic not yet delivered) — see deliver/deferred-scenarios.md
  it.skip("[@walking_skeleton @real-io @in-memory @driving_port @US-11] Maria adds a Trello card and it becomes a ticket, identical in structure to a native-form submission", async () => {
    // Given the "Fenwick Product Backlog" Trello board is configured for ingestion
    const app = createRealApiApp();
    const governanceRepository = createHttpGovernanceRepository({
      apiFetch: apiFetchAsRunner(app),
    });
    const trelloPort = createFakeTrelloIngestionPort({
      "fenwick-product-backlog": [makeCard()],
    });
    const board: TrelloIngestionBoardConfig = {
      boardId: "fenwick-product-backlog",
      defaultSubmitterHumanId: "maria-santos",
      isFirstPollForBoard: false,
    };
    const deps: TrelloIngestionPollerDependencies = {
      listBoards: async () => [board],
      trelloPort,
      governanceRepository,
    };

    // When Maria Santos adds a card "Add filter by region to Reports dashboard"
    await runBoardPollCycle(deps, board);

    // Then a ticket record and ticket-scoped channel are created, identical in structure to a
    // native-form submission
    const ticket = await governanceRepository.findTicketBySourceRef({
      source: "TRELLO",
      sourceRef: "card-1043",
    });
    expect(ticket).not.toBeNull();
    expect(ticket?.source).toBe("TRELLO");
    expect(ticket?.title).toBe("Add filter by region to Reports dashboard");
  });

  it("[@driving_adapter @real-io @US-11] a governance-team member registers a board for ingestion and can observe its poll status", async () => {
    const app = createRealApiApp();
    const cookie = await loginAsAdmin(app);
    const request = authedRequest(app, cookie);

    // Given a governance-team member wants to configure a board for ingestion
    // When they register "fenwick-product-backlog" for ingestion
    const registerRes = await request("/api/trello-ingestion/boards", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        boardId: "fenwick-product-backlog",
        defaultSubmitterHumanId: "maria-santos",
      }),
    });

    // Then the board is registered and its sync status becomes observable
    expect(registerRes.status).toBe(201);

    const listRes = await request("/api/trello-ingestion/boards");
    expect(listRes.status).toBe(200);
    const boards = (await listRes.json()) as Array<{ boardId: string; lastPollStatus?: string }>;
    expect(boards.map((entry) => entry.boardId)).toContain("fenwick-product-backlog");
  });

  it("[@US-11] a newly registered board's poll status is observable as not-yet-polled", async () => {
    const app = createRealApiApp();
    const cookie = await loginAsAdmin(app);
    const request = authedRequest(app, cookie);

    // Given a governance-team member has not yet registered any board
    // When they register "fenwick-product-backlog" for ingestion
    await request("/api/trello-ingestion/boards", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        boardId: "fenwick-product-backlog",
        defaultSubmitterHumanId: "maria-santos",
      }),
    });

    // Then GET exposes lastPolledAt/lastPollStatus/lastPollError as the queryable
    // sync-failure observability surface (US-11 domain example 3), all still unset
    const listRes = await request("/api/trello-ingestion/boards");
    const boards = (await listRes.json()) as Array<{
      boardId: string;
      lastPolledAt: number | null;
      lastPollStatus: string | null;
      lastPollError: string | null;
    }>;
    const board = boards.find((entry) => entry.boardId === "fenwick-product-backlog");
    expect(board).toMatchObject({
      lastPolledAt: null,
      lastPollStatus: null,
      lastPollError: null,
    });
  });

  it("[@US-11] a governance-team member disables an existing board's ingestion via PATCH", async () => {
    const app = createRealApiApp();
    const cookie = await loginAsAdmin(app);
    const request = authedRequest(app, cookie);

    // Given a board is already registered for ingestion
    await request("/api/trello-ingestion/boards", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        boardId: "fenwick-product-backlog",
        defaultSubmitterHumanId: "maria-santos",
      }),
    });

    // When a governance-team member disables it
    const patchRes = await request("/api/trello-ingestion/boards/fenwick-product-backlog", {
      method: "PATCH",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ enabled: false }),
    });

    // Then the update is accepted and reflected in the board's config
    expect(patchRes.status).toBe(200);
    const patched = (await patchRes.json()) as { enabled: boolean };
    expect(patched.enabled).toBe(false);

    const listRes = await request("/api/trello-ingestion/boards");
    const boards = (await listRes.json()) as Array<{ boardId: string; enabled: boolean }>;
    const board = boards.find((entry) => entry.boardId === "fenwick-product-backlog");
    expect(board?.enabled).toBe(false);
  });

  // Note: a scenario asserting 403 for an authenticated-but-non-governance human is
  // intentionally not added here. This codebase's only human fixture today is the seeded
  // admin (acceptance-test-support.ts's loginAsAdmin), and admin is now a real governance-team
  // member (the fixture this DISTILL wave's DWD-03 stand-in convention was extended to require
  // for this step). Adding a second, logged-in-but-non-governance human would require a further
  // acceptance-test-support.ts extension (a second seeded credential set) beyond the small,
  // justified addition already made for this step. `canManageTrelloIngestion`'s false-path
  // (isHumanUser but not a governance member) is still exercised indirectly: the "no session"
  // scenario below proves the route is gated at all, and `canManageAgent`'s equivalent
  // ownership-based false-path is already covered by pre-existing agents.ts tests using this
  // same access-control shape.

  // DEFERRED: needs a real `tickets` row (ticket-classification's POST /api/tickets insert
  // logic not yet delivered) — see deliver/deferred-scenarios.md
  it.skip("[@US-11] moving an existing card between lists does not create a duplicate ticket", async () => {
    const app = createRealApiApp();
    const governanceRepository = createHttpGovernanceRepository({
      apiFetch: apiFetchAsRunner(app),
    });
    // Given TICKET-1043 was already ingested from a Trello card sitting in "Backlog"
    const cardInBacklog = makeCard({ listId: "list-backlog" });
    const board: TrelloIngestionBoardConfig = {
      boardId: "fenwick-product-backlog",
      defaultSubmitterHumanId: "maria-santos",
      isFirstPollForBoard: false,
    };
    const firstPollDeps: TrelloIngestionPollerDependencies = {
      listBoards: async () => [board],
      trelloPort: createFakeTrelloIngestionPort({ "fenwick-product-backlog": [cardInBacklog] }),
      governanceRepository,
    };
    await runBoardPollCycle(firstPollDeps, board);

    // When that same card is moved to "In Progress"
    const cardMovedToInProgress = makeCard({ listId: "list-in-progress" });
    const secondPollDeps: TrelloIngestionPollerDependencies = {
      listBoards: async () => [board],
      trelloPort: createFakeTrelloIngestionPort({
        "fenwick-product-backlog": [cardMovedToInProgress],
      }),
      governanceRepository,
    };
    await runBoardPollCycle(secondPollDeps, board);

    // Then no duplicate ticket record is created for the same card id
    const ticket = await governanceRepository.findTicketBySourceRef({
      source: "TRELLO",
      sourceRef: "card-1043",
    });
    expect(ticket).not.toBeNull();
  });

  // DEFERRED: needs a real `tickets` row (ticket-classification's POST /api/tickets insert
  // logic not yet delivered) — see deliver/deferred-scenarios.md
  it.skip("[@US-11] ingestion recovers from a temporary Trello API outage without silently missing the card", async () => {
    const app = createRealApiApp();
    const governanceRepository = createHttpGovernanceRepository({
      apiFetch: apiFetchAsRunner(app),
    });
    const board: TrelloIngestionBoardConfig = {
      boardId: "fenwick-product-backlog",
      defaultSubmitterHumanId: "maria-santos",
      isFirstPollForBoard: false,
    };

    // Given the Trello API is unreachable when a new card is added
    const outageDeps: TrelloIngestionPollerDependencies = {
      listBoards: async () => [board],
      trelloPort: {
        async listCards() {
          throw new Error("Trello API unreachable");
        },
      },
      governanceRepository,
    };
    await expect(runBoardPollCycle(outageDeps, board)).rejects.toThrow();

    // When ingestion next runs after the API recovers
    const recoveredDeps: TrelloIngestionPollerDependencies = {
      listBoards: async () => [board],
      trelloPort: createFakeTrelloIngestionPort({ "fenwick-product-backlog": [makeCard()] }),
      governanceRepository,
    };
    await runBoardPollCycle(recoveredDeps, board);

    // Then the card is ingested successfully and no card is silently missed
    const ticket = await governanceRepository.findTicketBySourceRef({
      source: "TRELLO",
      sourceRef: "card-1043",
    });
    expect(ticket).not.toBeNull();
  });

  // DEFERRED: needs a real `tickets` row (ticket-classification's POST /api/tickets insert
  // logic not yet delivered) — see deliver/deferred-scenarios.md
  it.skip("[@property @US-11] two near-simultaneous syncs of the same card never create two ticket records", async () => {
    const app = createRealApiApp();
    const governanceRepository = createHttpGovernanceRepository({
      apiFetch: apiFetchAsRunner(app),
    });
    const board: TrelloIngestionBoardConfig = {
      boardId: "fenwick-product-backlog",
      defaultSubmitterHumanId: "maria-santos",
      isFirstPollForBoard: false,
    };
    const deps: TrelloIngestionPollerDependencies = {
      listBoards: async () => [board],
      trelloPort: createFakeTrelloIngestionPort({ "fenwick-product-backlog": [makeCard()] }),
      governanceRepository,
    };

    // Given a scheduled poll and a manually-triggered re-sync both observe the same new card
    // When both syncs run within the same second
    await Promise.allSettled([runBoardPollCycle(deps, board), runBoardPollCycle(deps, board)]);

    // Then only one ticket record is created for that card, for any interleaving of the two
    // syncs (a correctness invariant, not a single-example assertion)
    const ticket = await governanceRepository.findTicketBySourceRef({
      source: "TRELLO",
      sourceRef: "card-1043",
    });
    expect(ticket).not.toBeNull();
  });

  // DEFERRED: needs a real `tickets` row (ticket-classification's POST /api/tickets insert
  // logic not yet delivered) — see deliver/deferred-scenarios.md
  it.skip("[@US-11] ingested tickets are created the same way a native-form submission is created", async () => {
    const app = createRealApiApp();
    const cookie = await loginAsAdmin(app);
    const request = authedRequest(app, cookie);
    const governanceRepository = createHttpGovernanceRepository({
      apiFetch: apiFetchAsRunner(app),
    });
    const board: TrelloIngestionBoardConfig = {
      boardId: "fenwick-product-backlog",
      defaultSubmitterHumanId: "maria-santos",
      isFirstPollForBoard: false,
    };
    const deps: TrelloIngestionPollerDependencies = {
      listBoards: async () => [board],
      trelloPort: createFakeTrelloIngestionPort({ "fenwick-product-backlog": [makeCard()] }),
      governanceRepository,
    };

    // Given a submitter files a ticket the native way
    const nativeRes = await request("/api/tickets", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ title: "Fix Firefox layout bug" }),
    });

    // When the same card also proceeds through Trello ingestion
    await runBoardPollCycle(deps, board);

    // Then both entered through the same ticket-creation contract, with no source-specific
    // branching visible to the submitter
    expect(nativeRes.status).toBe(201);
    const trelloTicket = await governanceRepository.findTicketBySourceRef({
      source: "TRELLO",
      sourceRef: "card-1043",
    });
    expect(trelloTicket).not.toBeNull();
  });

  it("[@US-11] a submitter without any session cannot configure Trello ingestion boards", async () => {
    const app = createRealApiApp();

    // Given someone with no authenticated session at all attempts to register a board
    // When they call the board registration action
    const res = await app.request("http://localhost/api/trello-ingestion/boards", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ boardId: "unauthorized-board", defaultSubmitterHumanId: "devon-park" }),
    });

    // Then the request is rejected, never silently accepted
    expect(res.status).toBe(401);
  });

  const hasTrelloContractFixture = existsSync(
    `${process.env.HOME ?? ""}/.orgops-trello-cli-contract-fixture`,
  );

  it.skipIf(!hasTrelloContractFixture)("[@requires_external @US-11] the trello-cli CLI invocation contract remains stable", async () => {
    // Given real Trello credentials and a fixed-contract fixture are available in this
    // environment (a fixed-input/fixed-expected-shape regression test against the actual
    // trello-cli invocation, per brief.md "External Integrations Requiring Contract Awareness")
    // When the board reader lists cards for a known fixture board
    // Then the CLI's JSON output shape matches what TrelloCliBoardReader depends on
    //
    // Skipped by default (no fixture/credentials in this environment) — this is the
    // recommended CI-only smoke test named by the architecture brief, not part of the
    // fast local acceptance suite.
    expect(true).toBe(true);
  });
});

import { describe, expect, it } from "vitest";
import { authedRequest, createRealApiApp, loginAsAdmin } from "./acceptance-test-support";
import { evaluateGuardrailForCompletion } from "./guardrail-evaluator";

// US-12: Ticket Submitter Reviews and Approves or Requests Changes to Completed Implementation.
// Traceability: docs/feature/multi-source-ingestion-governance/discuss/user-stories.md US-12.
//
// Walking-Skeleton Strategy B: real SQLite + real Hono API app for all local I/O. This story
// has no costly external dependency (unlike US-11's Trello CLI), so every HTTP scenario here is
// @real-io through the real driving port (the HTTP route), per Mandate 1 (hexagonal boundary
// enforcement) — internal pure decision functions (decideApprove/decideRequestChanges/
// decideGovernanceSignoff in governance-approval-handler.ts) are exercised indirectly through
// these routes, never called directly from acceptance tests. The Guardrail Evaluator (a
// separate, event-consuming component with no HTTP surface of its own) is exercised directly,
// mirroring intent-watchdog.ts's directly-called pure-function shape.
//
// Every scenario authenticates as the seeded admin human (this codebase's only human fixture
// today) except the one scenario that deliberately omits a session, which now correctly expects
// 401 (no fixture yet distinguishes "authenticated but wrong role" from "not authenticated" —
// that would require a second human + team-membership fixture the ticket-classification track
// does not provide yet).

describe("US-12: submitter approve/request-changes governance gate", () => {
  // DEFERRED: needs a real, queryable `nwave_runs`/`nwave_run_completions` row for `run-1043`
  // (nwave-invocation-engine/progress-trust-ux not yet delivered) — see deliver/deferred-scenarios.md
  it.skip("[@walking_skeleton @real-io @driving_port @US-12] Maria approves a completed implementation and the ticket is marked resolved", async () => {
    const app = createRealApiApp();
    const cookie = await loginAsAdmin(app);
    const request = authedRequest(app, cookie);

    // Given TICKET-1043's completion summary shows 6/6 scenarios passed
    // When Maria Santos selects "Approve"
    const approveRes = await request("/api/nwave-runs/run-1043/completion-summary/approve", {
      method: "POST",
    });

    // Then TICKET-1043 is marked resolved
    expect(approveRes.status).toBe(200);
    const body = (await approveRes.json()) as { ticketResolutionStatus?: string };
    expect(body.ticketResolutionStatus).toBe("RESOLVED");
  });

  // DEFERRED: needs a real, queryable `nwave_runs`/`nwave_run_completions` row for `run-1042`
  // (nwave-invocation-engine/progress-trust-ux not yet delivered) — see deliver/deferred-scenarios.md
  it.skip("[@US-12] Devon requests changes with specific feedback and the original context is preserved", async () => {
    const app = createRealApiApp();
    const cookie = await loginAsAdmin(app);
    const request = authedRequest(app, cookie);

    // Given TICKET-1042's completion summary is posted
    // When Devon Park selects "Request changes" and notes "handles Safari but breaks on Firefox now"
    const res = await request("/api/nwave-runs/run-1042/completion-summary/request-changes", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ note: "handles Safari but breaks on Firefox now" }),
    });

    // Then a new implementation cycle starts scoped to that feedback, and the original
    // context/history is preserved, not discarded
    expect(res.status).toBe(200);
    const body = (await res.json()) as { newRunId?: string; channelId?: string };
    expect(body.newRunId).toBeTruthy();
  });

  // DEFERRED: needs a real, queryable `nwave_runs`/`nwave_run_completions` row for `run-held`
  // (nwave-invocation-engine/progress-trust-ux not yet delivered) — see deliver/deferred-scenarios.md
  it.skip("[@US-12] a run that touched a file outside the guardrail allowlist requires governance sign-off before Maria can approve", async () => {
    const app = createRealApiApp();
    const cookie = await loginAsAdmin(app);
    const request = authedRequest(app, cookie);

    // Given a completed run touched a file outside the configured guardrail allowlist
    // (governance_hold_reason set by the Guardrail Evaluator)
    // When Maria attempts to approve before Priya reviews the exception
    const prematureApproveRes = await request(
      "/api/nwave-runs/run-held/completion-summary/approve",
      { method: "POST" },
    );

    // Then "Approve" is not available to Maria until Priya provides explicit sign-off — a
    // structural rejection (403), not merely absent from the UI
    expect(prematureApproveRes.status).toBe(403);

    // When Priya Nair reviews the flagged exception and signs off
    const signoffRes = await request(
      "/api/nwave-runs/run-held/completion-summary/governance-signoff",
      { method: "POST" },
    );
    expect(signoffRes.status).toBe(200);

    // Then Approve becomes available
    const approveAfterSignoffRes = await request(
      "/api/nwave-runs/run-held/completion-summary/approve",
      { method: "POST" },
    );
    expect(approveAfterSignoffRes.status).toBe(200);
  });

  // DEFERRED: needs a real, queryable `nwave_runs`/`nwave_run_completions` row for `run-1043`
  // (nwave-invocation-engine/progress-trust-ux not yet delivered) — see deliver/deferred-scenarios.md
  it.skip("[@US-12] anyone with governance access can see who approved TICKET-1043 and when", async () => {
    const app = createRealApiApp();
    const cookie = await loginAsAdmin(app);
    const request = authedRequest(app, cookie);

    // Given TICKET-1043 was approved by Maria Santos
    await request("/api/nwave-runs/run-1043/completion-summary/approve", { method: "POST" });

    // When anyone with governance access reviews the ticket history
    const historyRes = await request("/api/nwave-runs/run-1043/cycle-history");

    // Then they can see who approved it and when
    expect(historyRes.status).toBe(200);
    const history = (await historyRes.json()) as Array<{
      eventType?: string;
      actorId?: string;
      createdAt?: number;
    }>;
    expect(history.some((entry) => entry.eventType === "APPROVED" && entry.actorId)).toBe(true);
  });

  // DEFERRED: needs a real, queryable `nwave_runs`/`nwave_run_completions` row for
  // `run-no-file-data` (nwave-invocation-engine/progress-trust-ux not yet delivered) — see
  // deliver/deferred-scenarios.md
  it.skip("[@US-12] guardrail evaluation fails closed to governance hold when changed-file data is unavailable", async () => {
    const app = createRealApiApp();
    const cookie = await loginAsAdmin(app);
    const request = authedRequest(app, cookie);

    // Given a run completes without changedFilePaths data (true for every run today, since the
    // DELIVER-wave output contract gap remains open) — this is the priority-1
    // correctness/auditability quality attribute: never fail open
    // When the submitter attempts to approve immediately after completion
    const approveRes = await request("/api/nwave-runs/run-no-file-data/completion-summary/approve", {
      method: "POST",
    });

    // Then approval is withheld pending governance sign-off (403), never silently allowed (200)
    expect(approveRes.status).toBe(403);
  });

  // DEFERRED: needs a real, queryable `nwave_runs`/`nwave_run_completions` row for
  // `run-held-for-anyone` (nwave-invocation-engine/progress-trust-ux not yet delivered) — see
  // deliver/deferred-scenarios.md
  it.skip("[@property @US-12] Approve is never available while a run is on governance hold, regardless of who requests it", async () => {
    const app = createRealApiApp();
    const cookie = await loginAsAdmin(app);
    const request = authedRequest(app, cookie);

    // Given any run currently on governance hold
    // When several different actor identities all attempt to approve it directly (the
    // authenticated session is the only real fixture available; the actor-id header stands in
    // for "any requester", since the gate must be structural, not requester-dependent)
    const attempts = await Promise.all(
      ["maria-santos", "priya-nair", "unknown-actor"].map((actor) =>
        request("/api/nwave-runs/run-held-for-anyone/completion-summary/approve", {
          method: "POST",
          headers: { "x-orgops-acting-as": actor },
        }),
      ),
    );

    // Then none of them succeed — every attempt is rejected with the same structural 403, for
    // any requester, not merely "not 200" (which a not-implemented route would also satisfy)
    for (const res of attempts) {
      expect(res.status).toBe(403);
    }
  });

  it("[@US-12] an unauthorized governance sign-off attempt is rejected before any write", async () => {
    const app = createRealApiApp();

    // Given someone with no authenticated session attempts to sign off
    // When they call the governance-signoff action
    const res = await app.request(
      "http://localhost/api/nwave-runs/run-held/completion-summary/governance-signoff",
      { method: "POST" },
    );

    // Then the request is rejected before any write
    expect(res.status).toBe(401);
  });

  // DEFERRED: needs a real, queryable `nwave_runs`/`nwave_run_completions` row for `run-1043`
  // (nwave-invocation-engine/progress-trust-ux not yet delivered) — see deliver/deferred-scenarios.md
  it.skip("[@US-12] a redelivered approval action is a no-op, not a second decision", async () => {
    const app = createRealApiApp();
    const cookie = await loginAsAdmin(app);
    const request = authedRequest(app, cookie);

    // Given TICKET-1043 was already approved once
    await request("/api/nwave-runs/run-1043/completion-summary/approve", { method: "POST" });

    // When the same approve action is redelivered (e.g. a retried webhook/client call)
    const redeliveredRes = await request("/api/nwave-runs/run-1043/completion-summary/approve", {
      method: "POST",
    });

    // Then it is a no-op — still resolved, no duplicate audit row
    expect(redeliveredRes.status).toBe(200);
    const historyRes = await request("/api/nwave-runs/run-1043/cycle-history");
    const history = (await historyRes.json()) as Array<{ eventType?: string }>;
    expect(history.filter((entry) => entry.eventType === "APPROVED")).toHaveLength(1);
  });

  it("[@driving_adapter @real-io @US-12] a governance-team member manages the guardrail allowlist and sees new patterns reflected in governance decisions", async () => {
    const app = createRealApiApp();
    const cookie = await loginAsAdmin(app);
    const request = authedRequest(app, cookie);

    // Given a governance-team member wants to allow a new path pattern
    // When they add "src/**" to the allowlist
    const addRes = await request("/api/guardrail-allowlist", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ pathPattern: "src/**" }),
    });
    expect(addRes.status).toBe(201);
    const added = (await addRes.json()) as { id?: string };

    // Then the pattern appears in the listing
    const listRes = await request("/api/guardrail-allowlist");
    expect(listRes.status).toBe(200);
    const entries = (await listRes.json()) as Array<{ pathPattern?: string }>;
    expect(entries.map((entry) => entry.pathPattern)).toContain("src/**");

    // When they remove it
    const deleteRes = await request(`/api/guardrail-allowlist/${added.id}`, { method: "DELETE" });

    // Then it is removed
    expect(deleteRes.status).toBe(204);
  });

  // Note (step 02-02): a scenario asserting 403 for an authenticated-but-non-governance human
  // is intentionally not added here, for the same reason trello-ingestion.test.ts's equivalent
  // note documents: this codebase's only human fixture today is the seeded admin
  // (acceptance-test-support.ts's loginAsAdmin), and admin is now a real governance-team
  // member. Adding a second, logged-in-but-non-governance human would require a further
  // acceptance-test-support.ts extension beyond this step's scope.
  // `canManageTrelloIngestion`'s false-path is still exercised indirectly here: the
  // "unauthorized governance sign-off attempt" scenario above proves this feature's routes are
  // gated at all (global auth gate, no session -> 401 before any handler runs), and
  // trello-ingestion.test.ts already documents the equivalent gap for the same access-control
  // function reused by this route file.

  it("[@US-12] the guardrail evaluator itself holds every completion for governance review while file-change data is unavailable", () => {
    // Given a run completes and its changedFilePaths data is unavailable (true for every run
    // today, per ADR-0010)
    // When the Guardrail Evaluator processes the completion event directly (this component's
    // own driving port, mirroring intent-watchdog.ts's directly-called pure-function shape)
    // Then it holds for governance review with an explicit, honest reason — never silently
    // allowing approval
    const decision = evaluateGuardrailForCompletion({ runId: "run-no-file-data" }, []);
    expect(decision.approvalStatus).toBe("GOVERNANCE_HOLD");
  });

  it("[@US-12] the guardrail evaluator clears every path covered by the allowlist", () => {
    // Given a run's changedFilePaths are all covered by the allowlist
    // When the Guardrail Evaluator processes the completion event directly
    const decision = evaluateGuardrailForCompletion(
      { runId: "run-covered", changedFilePaths: ["src/foo.ts", "src/bar.ts"] },
      [{ id: "allow-1", pathPattern: "src/**" }],
    );

    // Then approval becomes available immediately, with no governance step
    expect(decision.approvalStatus).toBe("PENDING");
  });

  it("[@US-12] the guardrail evaluator holds for governance review and names the uncovered path when only some changed paths are covered", () => {
    // Given a run's changedFilePaths include one path outside every allowlist pattern
    // When the Guardrail Evaluator processes the completion event directly
    const decision = evaluateGuardrailForCompletion(
      { runId: "run-partially-covered", changedFilePaths: ["src/foo.ts", "infra/terraform/main.tf"] },
      [{ id: "allow-1", pathPattern: "src/**" }],
    );

    // Then it holds for governance review, naming the specific uncovered path so a reviewer
    // knows exactly what to check — not merely "some path is uncovered"
    expect(decision.approvalStatus).toBe("GOVERNANCE_HOLD");
    expect(decision.governanceHoldReason).toContain("infra/terraform/main.tf");
  });
});

import { describe, expect, it } from "vitest";
import { authedRequest, createRealApiApp, loginAsAdmin } from "./acceptance-test-support";
import {
  composeFailureRecoveryGuidance,
  MAX_AUTO_RETRY_COUNT,
  type FailureCompletionEvent,
} from "./failure-recovery-advisor";
import { scanRunForStaleness, type RunningRunSnapshot } from "./stuck-run-detector";

// US-13: Failed or Stuck Implementation Runs Are Surfaced With Recovery Options.
// Traceability: docs/feature/multi-source-ingestion-governance/discuss/user-stories.md US-13.
//
// Failure/Recovery Advisor and Stuck-Run Detector are event-consuming/interval-scheduled
// internal components with no external caller — their driving port is the exported
// pure-processing function itself, called directly with an explicit input, mirroring
// intent-watchdog.ts's own directly-called-function shape (ingestIntentEvents/
// collectDueIntentTimeouts). Retry/Escalate/Close/cycle-history are genuine HTTP actions a
// human triggers, so those scenarios go through the real driving port: the HTTP route.

function makeFailureEvent(overrides: Partial<FailureCompletionEvent> = {}): FailureCompletionEvent {
  return {
    runId: "run-1042",
    outcome: "FAILED",
    retryCount: 0,
    whatCompleted: "Classification and confirmation completed",
    whatFailed: "DELIVER wave: test suite failed to compile",
    rawOutputUrl: "https://orgops.local/runs/run-1042/raw-output",
    ...overrides,
  };
}

function makeRunningRun(overrides: Partial<RunningRunSnapshot> = {}): RunningRunSnapshot {
  return {
    runId: "run-1043",
    lastOutputAt: 0,
    currentWaveStatus: "DELIVER",
    waveSequence: 1,
    alreadyFlagged: false,
    ...overrides,
  };
}

describe("US-13: failed or stuck runs surface recovery options", () => {
  it("[@walking_skeleton @driving_port @US-13] Devon sees a clear, non-blaming summary within 2 minutes of a failed run", () => {
    // Given TICKET-1042's implementation run fails during the DELIVER wave
    const event = makeFailureEvent();

    // When the run terminates and the Failure/Recovery Advisor processes the completion event
    const guidance = composeFailureRecoveryGuidance(event);

    // Then it explains what was completed, what failed, and a suggested next step, and Devon
    // is never shown a raw stack trace without plain-language context
    expect(guidance.message).toContain(event.whatCompleted);
    expect(guidance.message).toContain(event.whatFailed);
    expect(guidance.suggestedNextStep).toBe("RETRY");
    expect(guidance.retryAvailable).toBe(true);
  });

  // DEFERRED: stuck-run-detector.ts must call the shared `Run Activity Deriver`
  // (packages/schemas/src/run-activity.ts), a progress-trust-ux prerequisite scaffold that
  // still throws unconditionally (ADR-0012 forbids a second "stale" definition) — see
  // "Architectural Note" in deliver/deferred-scenarios.md
  it.skip("[@US-13] TICKET-1043's stalled run is proactively flagged, not silently left for Maria to discover", () => {
    // Given TICKET-1043's run has produced no activity for 30 minutes during a wave that
    // typically takes 5 minutes
    const staleRun = makeRunningRun({ lastOutputAt: 0, alreadyFlagged: false });
    const nowMs = 30 * 60_000;
    const staleThresholdMs = 10 * 60_000;

    // When the staleness threshold is exceeded and the Stuck-Run Detector scans this run
    const result = scanRunForStaleness(staleRun, nowMs, staleThresholdMs);

    // Then the run is proactively flagged as possibly stuck
    expect(result.action).toBe("FLAG");
  });

  it("[@property @US-13] raw stack traces are never shown without plain-language context, for any failure", () => {
    // Given any failed run with a raw-output link
    const events = [
      makeFailureEvent({ whatFailed: "TypeError: cannot read property of undefined" }),
      makeFailureEvent({ outcome: "HALTED", whatFailed: "Wave watchdog forcibly halted the run" }),
    ];

    // When the Failure/Recovery Advisor composes guidance for each
    const guidances = events.map((event) => composeFailureRecoveryGuidance(event));

    // Then the raw-output link is always paired with plain-language guidance, never bare
    for (const [index, guidance] of guidances.entries()) {
      expect(guidance.message).toContain(events[index]!.rawOutputUrl);
      expect(guidance.message).toContain(events[index]!.whatFailed);
    }
  });

  it("[@property @US-13] repeated failures always escalate instead of looping forever, regardless of failure reason", () => {
    // Given TICKET-1046's run has failed and been retried twice with the same underlying error
    const thirdFailure = makeFailureEvent({
      runId: "run-1046",
      retryCount: MAX_AUTO_RETRY_COUNT,
    });

    // When the third failure occurs
    const guidance = composeFailureRecoveryGuidance(thirdFailure);

    // Then "Retry" is no longer offered and escalation is suggested, for any run once the
    // threshold is met (not just this one example)
    expect(guidance.suggestedNextStep).toBe("ESCALATE");
    expect(guidance.retryAvailable).toBe(false);
  });

  it("[@US-13] retry remains available one attempt before the escalation threshold", () => {
    // Given TICKET-1046's run has failed and been retried one fewer time than the threshold
    const eventBelowThreshold = makeFailureEvent({
      runId: "run-1046",
      retryCount: MAX_AUTO_RETRY_COUNT - 1,
    });

    // When the Failure/Recovery Advisor composes guidance
    const guidance = composeFailureRecoveryGuidance(eventBelowThreshold);

    // Then "Retry" is still offered — the threshold has not yet been reached
    expect(guidance.suggestedNextStep).toBe("RETRY");
    expect(guidance.retryAvailable).toBe(true);
  });

  it("[@US-13] escalation persists for retry counts beyond the threshold, not only exactly at it", () => {
    // Given TICKET-1046's run has already exceeded the escalation threshold
    const eventAboveThreshold = makeFailureEvent({
      runId: "run-1046",
      retryCount: MAX_AUTO_RETRY_COUNT + 3,
    });

    // When the Failure/Recovery Advisor composes guidance
    const guidance = composeFailureRecoveryGuidance(eventAboveThreshold);

    // Then escalation still applies — the rule is "at or above", not "exactly equal to"
    expect(guidance.suggestedNextStep).toBe("ESCALATE");
    expect(guidance.retryAvailable).toBe(false);
  });

  // DEFERRED: needs a real, queryable `nwave_runs`/`nwave_run_completions` row for `run-1042`
  // (nwave-invocation-engine/progress-trust-ux not yet delivered) — see deliver/deferred-scenarios.md
  it.skip("[@driving_adapter @real-io @US-13] Devon retries a failed run with one action, without re-entering information", async () => {
    const app = createRealApiApp();
    const cookie = await loginAsAdmin(app);
    const request = authedRequest(app, cookie);

    // Given TICKET-1042's run failed once with a transient error and retry is available
    // When Devon Park selects "Retry"
    const res = await request("/api/nwave-runs/run-1042/retry", { method: "POST" });

    // Then a new run starts using the same confirmed ticket intent, without re-entering
    // information
    expect(res.status).toBe(201);
    const body = (await res.json()) as { newRunId?: string };
    expect(body.newRunId).toBeTruthy();
  });

  // DEFERRED: stuck-run-detector.ts must call the shared `Run Activity Deriver`
  // (packages/schemas/src/run-activity.ts), a progress-trust-ux prerequisite scaffold that
  // still throws unconditionally (ADR-0012 forbids a second "stale" definition) — see
  // "Architectural Note" in deliver/deferred-scenarios.md
  it.skip("[@US-13] a stuck flag auto-clears once the run's activity resumes", () => {
    const run = makeRunningRun({ alreadyFlagged: true });

    // Given a run was previously flagged as possibly stuck
    // When activity resumes (fresh output observed on a later scan)
    const result = scanRunForStaleness(
      { ...run, lastOutputAt: 9_000_000 },
      9_000_100,
      10 * 60_000,
    );

    // Then the flag auto-clears — no manual dismissal needed
    expect(result.action).toBe("CLEAR");
  });

  // DEFERRED: needs a real, queryable `nwave_runs`/`nwave_run_completions` row for `run-1046`
  // (nwave-invocation-engine/progress-trust-ux not yet delivered) — see deliver/deferred-scenarios.md
  it.skip("[@driving_adapter @real-io @US-13] escalation and closure preserve accumulated context from prior attempts", async () => {
    const app = createRealApiApp();
    const cookie = await loginAsAdmin(app);
    const request = authedRequest(app, cookie);

    // Given TICKET-1046's run has exhausted its automatic retries
    // When the submitter escalates to a human developer
    const escalateRes = await request("/api/nwave-runs/run-1046/escalate", { method: "POST" });
    expect(escalateRes.status).toBe(200);

    // Then the accumulated context from every prior attempt is available via cycle history
    const historyRes = await request("/api/nwave-runs/run-1046/cycle-history");
    expect(historyRes.status).toBe(200);

    // And a ticket can also be closed as a terminal action
    const closeRes = await request("/api/nwave-runs/run-1046/close", { method: "POST" });
    expect(closeRes.status).toBe(200);
  });
});
